def laplacian_mod_ell(m, edges, ell):
    """L̄(z) = L(z) mod ℓ ∈ M_m(𝔽_ℓ[z,z^{-1}])。"""
    Fq = GF(ell)
    RF = LaurentPolynomialRing(Fq, 'w')
    w = RF.gen()
    Lbar = matrix(RF, m, m)
    for (u, v, a) in edges:
        if u == v:
            Lbar[u, u] += _sage_const_2  - w**a - w**(-a)
        else:
            Lbar[u, u] += _sage_const_1 
            Lbar[v, v] += _sage_const_1 
            Lbar[u, v] -= w**a
            Lbar[v, u] -= w**(-a)
    return Lbar


